  app.post("/api/voice/transcribe", requireAuth, uploadMiddleware.single("audio"), async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });
      const file = (req as any).file;
      if (!file) {
        return res.status(400).json({ error: "audio file is required" });
      }
      const fs = await import("fs");
      const audioBuffer = fs.readFileSync(file.path);
      let transcript = "";
      try {
        const { transcribeMedicalAudio } = await import("../gcp-medical-speech");
        const result = await transcribeMedicalAudio({ audioBase64: audioBuffer.toString("base64"), encoding: "WEBM_OPUS" }, userId);
        transcript = result.transcript || "";
      } catch (gcpErr: any) {
        // GCP medical speech is the only PHI-safe transcription path; OpenAI Whisper fallback removed.
        console.error("GCP medical speech transcription error:", gcpErr);
      }
      try { fs.unlinkSync(file.path); } catch (_) {}
      if (!transcript) {
        return res.status(422).json({ error: "Could not transcribe audio" });
      }
      auditLog(req, "voice_transcribe", "AudioTranscript", userId, { length: transcript.length });
      res.json({ transcript, text: transcript });
    } catch (error: any) {
      console.error("Voice transcribe error:", error);
      res.status(500).json({ error: "Failed to transcribe audio" });
    }
  });


  app.post("/api/said/mint", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });
      const { firstName, middleName, lastName, dob, idDocType, idDocNumber, residencyState, preferredLang, isVeteran, smsOptIn } = req.body as any;
      if (!firstName || !lastName || !idDocType || !idDocNumber || !residencyState) {
        return res.status(400).json({ error: "firstName, lastName, idDocType, idDocNumber, residencyState required" });
      }
      const { generateSaidPatientId, normalizeName, encryptField, hashIdDocument } = await import("../said-patient-service");
      const encKey = process.env.PHI_ENCRYPTION_KEY;
      if (!encKey) {
        return res.status(500).json({ error: "PHI encryption key not configured" });
      }
      const existing = await db.select().from(patients).where(eq(patients.userId, userId)).limit(1);
      if (existing.length > 0) {
        return res.json({ saidPatientId: existing[0].saidPatientId, alreadyExists: true });
      }
      const saidPatientId = generateSaidPatientId(residencyState);
      const normalized = normalizeName(firstName, middleName, lastName);
      const newPatient = await db.insert(patients).values({
        saidPatientId,
        userId,
        nameFirstEnc: encryptField(normalized.nameFirst, encKey),
        nameMiddleEnc: encryptField(normalized.nameMiddle, encKey),
        nameLastEnc: encryptField(normalized.nameLast, encKey),
        hasNoMiddleName: normalized.isNMN,
        dobEnc: dob ? encryptField(dob, encKey) : null,
        idDocType,
        idDocHash: hashIdDocument(idDocNumber),
        residencyState: residencyState.toUpperCase().slice(0, 2),
        preferredLang: preferredLang || "en",
        isVeteran: isVeteran || false,
        smsOptIn: smsOptIn || false,
        smsOptInAt: smsOptIn ? new Date() : null,
      }).returning();
      auditLog(req, "said_mint", "Patient", saidPatientId, { userId });
      res.json({ saidPatientId, patientId: newPatient[0]?.id });
    } catch (error: any) {
      console.error("SAID mint error:", error);
      res.status(500).json({ error: "Failed to mint SAID Patient ID" });
    }
  });


