  app.post("/api/cross-app/token", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });
      const { cptCode, specialty } = req.body as any;

      const patientRows = await db.select({ saidPatientId: patients.saidPatientId }).from(patients).where(eq(patients.userId, userId)).limit(1);
      const saidPatientId = patientRows[0]?.saidPatientId;
      if (!saidPatientId || !cptCode || !specialty) {
        return res.status(400).json({ error: "SAID not found for user, or cptCode/specialty missing" });
      }
      const crypto = await import("crypto");
      const jti = crypto.randomUUID();
      const jwt = await import("jsonwebtoken");
      const secret = process.env.CROSS_APP_SECRET || process.env.PHI_ENCRYPTION_KEY;
      if (!secret) {
        return res.status(500).json({ error: "Cross-app secret not configured" });
      }
      const xtoken = jwt.default.sign({
        saidPatientId,
        hint: { cptCode, specialty },
        jti,
        iss: "https://tabulamedica.health",
        aud: "https://uninsurance.care",
      }, secret, { expiresIn: "15m" });
      auditLog(req, "cross_app_token", "DeepLink", saidPatientId, { cptCode, specialty, target: "uninsurance", jti });
      res.json({ xtoken });
    } catch (error: any) {
      console.error("Cross-app token error:", error);
      res.status(500).json({ error: "Failed to generate cross-app token" });
    }
  });


