  app.post("/api/moderation/action", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { communityId, actionType, targetUserId, targetPostId, targetCommentId, reason, duration, relatedReportId } = req.body as any;

      if (!communityId || !actionType) {
        return res.status(400).json({ error: "communityId and actionType are required" });
      }

      const memberships = await storage.getUserCommunityMemberships(userId);
      const membership = memberships.find((m: any) => m.communityId === communityId);

      if (!membership || (membership.role !== "moderator" && membership.role !== "admin")) {
        return res.status(403).json({ error: "Moderator access required" });
      }

      let expiresAt = null;
      if (duration && (actionType === "mute_user" || actionType === "ban_user")) {
        expiresAt = new Date(Date.now() + duration * 60 * 60 * 1000);
      }

      const action = await storage.createModerationAction({
        moderatorId: userId,
        communityId,
        targetUserId: targetUserId || null,
        targetPostId: targetPostId || null,
        targetCommentId: targetCommentId || null,
        actionType,
        reason: reason || null,
        duration: duration || null,
        expiresAt,
        relatedReportId: relatedReportId || null,
      });

      if (actionType === "hide_post" && targetPostId) {
        await storage.hidePost(targetPostId);
      } else if (actionType === "hide_comment" && targetCommentId) {
        await storage.hideComment(targetCommentId);
      }

      if (targetUserId) {
        let newStatus = "active";
        let muteExpiresAt = null;
        let banExpiresAt = null;
        let banReason = null;

        if (actionType === "warn_user") {
          newStatus = "warned";
        } else if (actionType === "mute_user") {
          newStatus = "muted";
          muteExpiresAt = expiresAt;
        } else if (actionType === "ban_user") {
          newStatus = "banned";
          banExpiresAt = expiresAt;
          banReason = reason || null;
        } else if (actionType === "unban_user") {
          newStatus = "active";
        }

        const existingStatus = await storage.getCommunityUserStatus(targetUserId, communityId);
        const warningCount = (existingStatus?.warningCount || 0) + (actionType === "warn_user" ? 1 : 0);

        await storage.upsertCommunityUserStatus({
          userId: targetUserId,
          communityId,
          status: newStatus,
          warningCount,
          muteExpiresAt,
          banExpiresAt,
          banReason,
          lastWarningAt: actionType === "warn_user" ? new Date() : existingStatus?.lastWarningAt || null,
        });
      }

      if (relatedReportId) {
        await storage.updateContentReport(relatedReportId, {
          status: "action_taken",
          reviewedBy: userId,
          reviewedAt: new Date(),
          actionTaken: actionType,
        });
      }

      auditLog(req, `moderation_${actionType}`, "moderation", action.id);
      res.status(201).json(action);
    } catch (error) {
      console.error("Moderation action error:", error);
      res.status(500).json({ error: "Failed to perform moderation action" });
    }
  });


