  app.post("/api/communities/:id/goal-share", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const communityId = (req.params as any).id as string;

      const memberships = await storage.getUserCommunityMemberships(userId);
      const isMember = memberships.some((m: any) => m.communityId === communityId);
      if (!isMember) {
        return res.status(403).json({ error: "Must be a community member to share goals" });
      }

      const userStatus = await storage.getCommunityUserStatus(userId, communityId);
      if (userStatus && (userStatus.status === "muted" || userStatus.status === "banned")) {
        return res.status(403).json({ error: "You are not allowed to post in this community" });
      }

      const { goalCategory, milestoneTitle, progressPercent, insightText, privacyLevel, isAnonymous } = req.body as any;

      if (!goalCategory || !milestoneTitle) {
        return res.status(400).json({ error: "goalCategory and milestoneTitle are required" });
      }

      const share = await storage.createGoalProgressShare({
        userId,
        communityId,
        goalCategory,
        milestoneTitle,
        progressPercent: progressPercent || null,
        insightText: insightText || null,
        isAnonymous: isAnonymous !== false,
        displayName: isAnonymous !== false ? null : req.body.displayName || null,
        linkedPostId: null,
        privacyLevel: privacyLevel || "anonymized",
      });

      const post = await storage.createCommunityPost({
        communityId,
        authorId: userId,
        authorDisplayName: isAnonymous !== false ? "Anonymous Member" : (req.body.displayName || "Community Member"),
        postType: "milestone",
        title: milestoneTitle,
        content: insightText || `Reached ${progressPercent || 0}% progress on ${goalCategory} goal!`,
        tags: [goalCategory, "goal-progress"],
        isAnonymous: isAnonymous !== false,
        isPinned: false,
        isHidden: false,
      });

      await storage.createGoalProgressShare({
        ...share,
        linkedPostId: post.id,
      }).catch(() => {});

      auditLog(req, "goal_progress_shared", "goal_share", share.id);
      res.status(201).json({ share, post });
    } catch (error) {
      console.error("Share goal progress error:", error);
      res.status(500).json({ error: "Failed to share goal progress" });
    }
  });


