  app.post("/api/challenges/:id/contribute", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const membership = await storage.getUserTeamMembership(userId);
      
      if (!membership) {
        return res.status(400).json({ error: "Must be on a team" });
      }

      const participation = await storage.getTeamChallengeParticipation(
        membership.teamId, 
        (req.params as any).id as string
      );
      
      if (!participation) {
        return res.status(400).json({ error: "Team is not participating in this challenge" });
      }

      const contribution = await storage.createTeamChallengeContribution({
        userId,
        teamId: membership.teamId,
        challengeId: (req.params as any).id as string,
        contributionValue: req.body.value,
        contributionDate: new Date(),
        notes: req.body.notes || null,
      });

      const newProgress = (participation.currentProgress || 0) + req.body.value;
      const progressPercentage = Math.min(
        100, 
        Math.round((newProgress / participation.targetProgress) * 100)
      );

      await storage.updateTeamChallengeParticipation(participation.id, {
        currentProgress: newProgress,
        progressPercentage,
        contributingMembers: (participation.contributingMembers || 0) + 1,
        isCompleted: newProgress >= participation.targetProgress,
        completedAt: newProgress >= participation.targetProgress ? new Date() : null,
      });

      await storage.updateTeamMembership(membership.id, {
        contributedPoints: (membership.contributedPoints || 0) + req.body.value,
        weeklyContribution: (membership.weeklyContribution || 0) + req.body.value,
        lastContributionAt: new Date(),
      });

      res.status(201).json(contribution);
    } catch (error) {
      console.error("Contribute to challenge error:", error);
      res.status(500).json({ error: "Failed to log contribution" });
    }
  });


  app.get("/api/leaderboard/:period", async (req, res) => {
    try {
      const { period } = req.params as any;
      
      if (!["weekly", "monthly", "all_time"].includes(period)) {
        return res.status(400).json({ error: "Invalid period" });
      }

      let leaderboard = await storage.getTeamLeaderboard(period);
      
      if (!leaderboard) {
        const teams = await storage.getHealthTeams();
        const rankings = teams
          .sort((a: any, b: any) => {
            if (period === "weekly") return (b.weeklyPoints || 0) - (a.weeklyPoints || 0);
            if (period === "monthly") return (b.monthlyPoints || 0) - (a.monthlyPoints || 0);
            return (b.totalPoints || 0) - (a.totalPoints || 0);
          })
          .map((team: any, index: any) => ({
            teamId: team.id,
            teamName: team.name,
            rank: index + 1,
            points: period === "weekly" ? team.weeklyPoints : 
                    period === "monthly" ? team.monthlyPoints : team.totalPoints,
            memberCount: team.currentMembers,
          }));

        leaderboard = await storage.createTeamLeaderboard({
          period,
          periodStart: new Date(),
          rankings,
          totalTeams: teams.length,
        });
      }

      res.json(leaderboard);
    } catch (error) {
      console.error("Get leaderboard error:", error);
      res.status(500).json({ error: "Failed to get leaderboard" });
    }
  });

