  app.post("/api/care-pathways/generate", requireAuth, async (req, res) => {
    try {
      const { condition, conditionCode, category, patientContext } = req.body as any;
      const { generateConditionPathway } = await import("../ai-care-pathways");
      
      const generated = await generateConditionPathway(condition, conditionCode, category, patientContext);
      
      const pathway = await storage.createCarePathway({
        title: generated.title,
        description: generated.description,
        condition,
        conditionCode: conditionCode || null,
        category,
        targetDurationDays: generated.targetDurationDays,
        difficultyLevel: generated.difficultyLevel,
        isAiGenerated: true,
        aiGenerationPrompt: JSON.stringify({ condition, category, patientContext }),
        isTemplate: true,
        isPublished: false,
        outcomes: generated.outcomes,
        evidenceBase: generated.evidenceBase,
      });

      let stepIndex = 0;
      const allSteps = [];
      for (const phase of generated.phases) {
        for (const step of phase.steps) {
          allSteps.push({
            pathwayId: pathway.id,
            title: step.title,
            description: step.description,
            stepType: step.stepType,
            orderIndex: stepIndex++,
            phase: generated.phases.indexOf(phase) + 1,
            phaseName: phase.name,
            durationDays: step.durationDays,
            isMandatory: step.isMandatory,
            isMilestone: step.isMilestone,
            educationalContent: step.educationalContent || null,
            taskInstructions: step.taskInstructions || null,
            assessmentQuestions: step.assessmentQuestions || null,
            successCriteria: step.successCriteria,
            pointsReward: step.pointsReward,
          });
        }
      }

      const steps = await storage.createPathwaySteps(allSteps);
      
      auditLog(req, "care_pathway_generated", "pathway", pathway.id);
      res.status(201).json({ ...pathway, steps });
    } catch (error) {
      console.error("Generate care pathway error:", error);
      res.status(500).json({ error: "Failed to generate care pathway" });
    }
  });


