  app.post("/api/pathway-assignments", requireAuth, async (req, res) => {
    try {
      const { pathwayId, patientId, startDate, personalizedNotes } = req.body as any;
      
      const pathway = await storage.getCarePathway(pathwayId);
      if (!pathway) {
        return res.status(404).json({ error: "Pathway not found" });
      }

      const expectedEndDate = startDate 
        ? new Date(new Date(startDate).getTime() + (pathway.targetDurationDays * 24 * 60 * 60 * 1000))
        : null;

      const assignment = await storage.createPatientPathwayAssignment({
        pathwayId,
        patientId,
        assignedByProviderId: req.body.assignedByProviderId || null,
        status: startDate ? "active" : "pending",
        startDate: startDate ? new Date(startDate) : null,
        expectedEndDate,
        personalizedNotes: personalizedNotes || null,
        adherenceScore: 100,
        engagementScore: 100,
      });

      const steps = await storage.getPathwaySteps(pathwayId);
      for (let i = 0; i < steps.length; i++) {
        const step = steps[i];
        const dueDate = startDate && step.durationDays 
          ? new Date(new Date(startDate).getTime() + ((step.orderIndex + 1) * step.durationDays * 24 * 60 * 60 * 1000))
          : null;
          
        await storage.createPatientStepProgress({
          assignmentId: assignment.id,
          stepId: step.id,
          status: i === 0 ? "available" : "locked",
          dueDate,
        });
      }

      auditLog(req, "pathway_assigned", "assignment", assignment.id);
      res.status(201).json(assignment);
    } catch (error) {
      console.error("Create pathway assignment error:", error);
      res.status(500).json({ error: "Failed to create assignment" });
    }
  });


