  // Step Progress

  app.patch("/api/step-progress/:id", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { status, assessmentResponses, patientNotes } = req.body as any;
      
      const progress = await storage.getStepProgress((req.params as any).id as string);
      if (!progress) {
        return res.status(404).json({ error: "Step progress not found" });
      }

      const updates: any = { ...req.body };
      
      if (status === "completed" && progress.status !== "completed") {
        updates.completedAt = new Date();
        
        const step = await storage.getPathwayStep(progress.stepId);
        if (step) {
          updates.pointsEarned = step.pointsReward || 10;
        }

        const assignment = await storage.getPatientPathwayAssignment(progress.assignmentId);
        if (assignment) {
          const allProgress = await storage.getPatientStepProgress(progress.assignmentId);
          const completedCount = allProgress.filter((p: any) => p.status === "completed" || p.id === (req.params as any).id as string).length;
          const totalSteps = allProgress.length;
          const progressPercentage = Math.round((completedCount / totalSteps) * 100);
          
          await storage.updatePatientPathwayAssignment(progress.assignmentId, {
            stepsCompleted: completedCount,
            progressPercentage,
            totalPointsEarned: (assignment.totalPointsEarned || 0) + (updates.pointsEarned || 0),
            lastActivityAt: new Date(),
          });

          const nextProgress = allProgress.find((p: any) => p.status === "locked");
          if (nextProgress) {
            await storage.updatePatientStepProgress(nextProgress.id, { status: "available" });
          }

          await storage.createPathwayAdherenceLog({
            assignmentId: progress.assignmentId,
            stepId: progress.stepId,
            eventType: "step_completed",
            eventData: { assessmentResponses, patientNotes },
            adherenceImpact: 5,
          });
        }
      } else if (status === "in_progress" && progress.status === "available") {
        updates.startedAt = new Date();
        updates.attempts = (progress.attempts || 0) + 1;
        
        await storage.createPathwayAdherenceLog({
          assignmentId: progress.assignmentId,
          stepId: progress.stepId,
          eventType: "step_started",
          eventData: {},
          adherenceImpact: 2,
        });
      }

      const updated = await storage.updatePatientStepProgress((req.params as any).id as string, updates);
      res.json(updated);
    } catch (error) {
      console.error("Update step progress error:", error);
      res.status(500).json({ error: "Failed to update step progress" });
    }
  });


  app.post("/api/step-progress/:id/adapt-content", requireAuth, async (req, res) => {
    try {
      const { generateAdaptiveContent } = await import("../ai-care-pathways");
      
      const progress = await storage.getStepProgress((req.params as any).id as string);
      if (!progress) {
        return res.status(404).json({ error: "Step progress not found" });
      }

      const step = await storage.getPathwayStep(progress.stepId);
      if (!step) {
        return res.status(404).json({ error: "Step not found" });
      }

      const assignment = await storage.getPatientPathwayAssignment(progress.assignmentId);
      if (!assignment) {
        return res.status(404).json({ error: "Assignment not found" });
      }

      const allProgress = await storage.getPatientStepProgress(progress.assignmentId);
      const assessmentScores = allProgress
        .filter((p: any) => p.assessmentScore !== null)
        .map((p: any) => p.assessmentScore!);

      const adapted = await generateAdaptiveContent(
        step,
        {
          adherenceScore: assignment.adherenceScore || 100,
          engagementScore: assignment.engagementScore || 100,
          assessmentScores,
          completedSteps: assignment.stepsCompleted || 0,
          missedSteps: assignment.stepsMissed || 0,
          timeSpentMinutes: allProgress.reduce((sum: any, p: any) => sum + (p.timeSpentMinutes || 0), 0),
        },
        req.body.conditions || [],
        req.body.preferences
      );

      await storage.updatePatientStepProgress(progress.id, {
        adaptedContent: adapted,
      });

      res.json(adapted);
    } catch (error) {
      console.error("Adapt step content error:", error);
      res.status(500).json({ error: "Failed to adapt content" });
    }
  });

